def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Identify the long monochrome guide bar (a straight run with a bent arm).
    # Its color is the destination color for the indicated isolated/small motif.
    candidates = []
    for color in set(v for row in out for v in row):
        if color == 1:
            continue
        cells = [(r, c) for r in range(h) for c in range(w) if out[r][c] == color]
        if len(cells) >= 7:
            candidates.append((len(cells), color))
    guide = max(candidates)[1] if candidates else None
    if guide is None:
        return out
    # A one-cell 5 marker is recolored to the guide's color (demo 1).
    for r in range(h):
        for c in range(w):
            if out[r][c] == 5:
                n = sum(0 <= r+dr < h and 0 <= c+dc < w and out[r+dr][c+dc] == 5
                        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)))
                if n == 0:
                    out[r][c] = guide
    # Recolor the uppermost small component of color 7 nearest the guide bar.
    seen = set(); comps = []
    for r in range(h):
        for c in range(w):
            if out[r][c] != 7 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and out[ny][nx]==7 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            comps.append(comp)
    if comps:
        comp = min(comps, key=lambda q: (min(y for y,x in q), len(q), min(x for y,x in q)))
        # Only the small top-side motif is selected, not the other scattered motifs.
        for y,x in comp:
            out[y][x] = guide
    return out

